// Carrega base cadastral de investidores e perfis (representando o CSV)
return [
  { json: { id: 1, nome: "Carlos Silva", email: "carlos.silva@email.com", perfil: "Conservador", ativo: "USD", gatilho_max: -0.50 } },
  { json: { id: 2, nome: "Mariana Souza", email: "mariana.souza@email.com", perfil: "Moderado", ativo: "EUR", gatilho_max: -0.80 } },
  { json: { id: 3, nome: "Lucas Mendes", email: "lucas.mendes@email.com", perfil: "Agressivo", ativo: "BTC", gatilho_max: -1.50 } },
  { json: { id: 4, nome: "Beatriz Lima", email: "beatriz.lima@email.com", perfil: "Conservador", ativo: "USD", gatilho_max: -0.20 } },
  { json: { id: 5, nome: "Rafael Oliveira", email: "rafael.oliveira@email.com", perfil: "Agressivo", ativo: "BTC", gatilho_max: -2.00 } }
];

// Motor RPA: Analisa perfis de investidores cruzando com dados em tempo real
const items = $input.all();
const cotacoesAPI = items[0].json.USDBRL ? items[0].json : {};

const investidores = [
  { id: 1, nome: "Carlos Silva", email: "carlos.silva@email.com", perfil: "Conservador", ativo: "USDBRL", simbolo: "USD", gatilho_max: -0.50 },
  { id: 2, nome: "Mariana Souza", email: "mariana.souza@email.com", perfil: "Moderado", ativo: "EURBRL", simbolo: "EUR", gatilho_max: -0.80 },
  { id: 3, nome: "Lucas Mendes", email: "lucas.mendes@email.com", perfil: "Agressivo", ativo: "BTCBRL", simbolo: "BTC", gatilho_max: -1.50 },
  { id: 4, nome: "Beatriz Lima", email: "beatriz.lima@email.com", perfil: "Conservador", ativo: "USDBRL", simbolo: "USD", gatilho_max: -0.20 },
  { id: 5, nome: "Rafael Oliveira", email: "rafael.oliveira@email.com", perfil: "Agressivo", ativo: "BTCBRL", simbolo: "BTC", gatilho_max: -2.00 }
];

const recomendacoes = [];

investidores.forEach(inv => {
  const dadosMercado = cotacoesAPI[inv.ativo] || {};
  const cotacao = Number(parseFloat(dadosMercado.bid || 0).toFixed(4));
  const variacao = Number(parseFloat(dadosMercado.pctChange || 0).toFixed(2));
  const maxima = Number(parseFloat(dadosMercado.high || 0).toFixed(4));
  const minima = Number(parseFloat(dadosMercado.low || 0).toFixed(4));

  // Regra de decisao: Oportunidade de investimento identificada
  const horaDeInvestir = variacao <= inv.gatilho_max || variacao <= 0;

  const statusAcao = horaDeInvestir ? "HORA DE INVESTIR (Entrada Recomendada)" : "AGUARDAR (Mercado em alta)";
  const motivo = horaDeInvestir 
    ? `O ativo ${inv.simbolo} variou ${variacao}%, atingindo zona de oportunidade para perfil ${inv.perfil}.`
    : `O ativo ${inv.simbolo} subiu ${variacao}%. Recomendamos aguardar correcao.`;

  const emailBody = `Ola ${inv.nome},\n\n` +
    `Análise de Investimentos - Santander RPA\n` +
    `Perfil do Investidor: ${inv.perfil} | Ativo: ${inv.simbolo}\n` +
    `Cotacao Atual: R$ ${cotacao.toLocaleString('pt-BR', { minimumFractionDigits: 2 })} (${variacao}%)\n` +
    `Minima do Dia: R$ ${minima} | Maxima: R$ ${maxima}\n\n` +
    `🎯 Recomendacao: ${statusAcao}\n` +
    `💡 Parecer: ${motivo}\n\n` +
    `Atenciosamente,\nEquipe de Automacao e Investimentos Santander`;

  recomendacoes.append ? null : recomendacoes.push({
    id: inv.id,
    nome: inv.nome,
    email: inv.email,
    perfil: inv.perfil,
    ativo: inv.simbolo,
    cotacao: cotacao,
    variacao_pct: variacao,
    hora_de_investir: horaDeInvestir,
    recomendacao: statusAcao,
    email_corpo: emailBody
  });
});

const oportunidades = recomendacoes.filter(r => r.hora_de_investir);

return {
  status: "SUCESSO",
  total_analisados: recomendacoes.length,
  total_oportunidades: oportunidades.length,
  possui_oportunidades: oportunidades.length > 0 ? 1 : 0,
  investidores_com_oportunidade: oportunidades,
  todas_recomendacoes: recomendacoes,
  resumo_executivo: `Identificadas ${oportunidades.length} recomendacoes de investimento para envio imediato.`
};
